import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Apply cinematic primitives if any
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // Plane geometry – size derived from image aspect (default 1:0.6)
  const planeGeom = new PlaneGeometry(1, 0.6);
  const planeMat = new MeshBasicNodeMaterial();
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture (if provided)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // Text content
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    root.add(txt);
  }

  // Interaction handlers
  root.userData.handlers = {};

  // Hover rise‑in effect
  root.userData.handlers.hover = {
    enter: () => {
      gsap.to(planeMesh.position, {
        y: 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    leave: () => {
      gsap.to(planeMesh.position, {
        y: 0,
        duration: 0.5,
        ease: 'power2.out',
      });
    },
  };

  // Click emission
  root.userData.handlers.click = () => {
    ctx.emit('hub-journal.select');
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    planeGeom.dispose();
    if (planeMat.map) planeMat.map.dispose();
    planeMat.dispose();

    // Dispose primitives
    for (const p of primitiveInstances) {
      if (p.cleanup) p.cleanup();
    }

    // Kill any GSAP tweens on the mesh
    gsap.killTweensOf(planeMesh.position);
  };

  return root;
}
